arguments.command:
cd /app && python3 -c "
import subprocess
from pathlib import Path
d={}
for b in Path('sequences.fasta').read_text().split('>'):
  if not b.strip(): continue
  n,*s=b.split('\n'); d[n.strip()]=''.join(s).strip().upper()
i=d['input']; P=215
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
def tm(s): return float(subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',s],capture_output=True,text=True).stdout.strip())
for lr in range(15,46):
  r=rc(i[P-lr:P]); print(lr, round(tm(r),2), r[-1])
print()
for lf in range(15,30):
  print(lf, round(tm(i[P:P+lf]),2))
"

